/* @lc app=leetcode id=1489 lang=kotlin */ class Solution { fun findCriticalAndPseudoCriticalEdges(n: Int, edges: Array<IntArray>): List<List<Int>> = edges.indices.sortedBy { edges[it][2] }.let { sorted -> { ex: Int, inc: Int -> IntArray(n) { it }.let { parent -> DeepRecursiveFunction<Pair<IntArray, Int>, Int> { (p, i) -> if (p[i] == i) i else callRecursive(p to p[i]).also { p[i] = it } }.let { find -> (if (inc != -1) (edges[inc][2] to 1).also { parent[find(parent to edges[inc][0])] = find(parent to edges[inc][1]) } else 0 to 0).let { (initialW, initialC) -> sorted.fold(initialW to initialC) { (w, c), i -> if (i == ex || i == inc) w to c else find(parent to edges[i][0]).let { u -> find(parent to edges[i][1]).let { v -> if (u != v) (w + edges[i][2] to c + 1).also { parent[u] = v } else w to c } } }.let { (w, c) -> if (c == n - 1) w else Int.MAX_VALUE } } } } }.let { getMst -> getMst(-1, -1).let { base -> edges.indices.groupBy { i -> if (getMst(i, -1) > base) 0 else if (getMst(-1, i) == base) 1 else 2 }.let { map -> listOf(map[0] ?: emptyList(), map[1] ?: emptyList()) } } } } }